import { CACHE_KEYS } from '../config';
import Storage from '../utils/storage';
import { getLanguage } from '../apis/app';
export function getAppData() {
    return Storage.get(CACHE_KEYS.APP_DATA) || {};
}
export function isTranslate() {
    const { packageType, packageEndTime } = getAppData();
    return packageType > 0 && packageEndTime * 1000 > Date.now();
}
export async function getLanguageList() {
    return await getLanguage();
}
